  "plan.pro.2": { en: "Checkout step analytics|See at which step each customer stopped and exactly what was in their cart.", ro: "Statistici pe pașii comenzii|Vezi la ce pas s-a oprit fiecare client și ce anume avea în coș." },
  "plan.pro.3": { en: "Fully automatic abandoned-checkout e-mails|Semafor writes by itself to every customer who leaves checkout without ordering: elegant templates with the products from their cart, in the customer's language. It stops as soon as the order is placed.", ro: "E-mailuri complet automate pentru comenzile abandonate|Semafor scrie singur fiecărui client care părăsește finalizarea comenzii fără să comande: șabloane elegante, cu produsele din coșul lui, în limba clientului. Se oprește imediat ce comanda e plasată." },
  "plan.pro.4": { en: "A sequence of up to 3 reminders|1) About an hour after leaving — a friendly reminder.\n2) The next morning, in the customer's time zone — with a discount (15% by default) if the cart has none yet.\n3) On day 3 — a last chance with a bigger discount (20%), valid that day only.\nYou set the times and percentages.", ro: "O secvență de până la 3 reamintiri|1) La circa o oră după ce a plecat — o reamintire prietenoasă.\n2) A doua zi dimineață, la ora clientului — cu o reducere (implicit 15%), dacă în coș nu are deja una.\n3) În a treia zi — ultima șansă, cu o reducere mai mare (20%), valabilă doar în ziua aceea.\nOrele și procentele le alegi tu." },
  "plan.pro.5": { en: "Reminders even without an e-mail at checkout|If a pop-up subscriber leaves before typing their e-mail at checkout, Semafor recognises them by device and still sends the reminders to the address they subscribed with.", ro: "Reamintiri chiar și fără e-mail la finalizare|Dacă un abonat din pop-up pleacă înainte să-și scrie e-mailul la finalizarea comenzii, Semafor îl recunoaște după dispozitiv și îi trimite reamintirile pe adresa cu care s-a abonat." },
  "plan.needBanner": { en: "To use {feature} you need the {plan} plan", ro: "Pentru {feature} ai nevoie de planul {plan}" },
  "plan.needBody": { en: "Choose a plan below — it activates instantly, no need to reinstall the app.", ro: "Alege planul mai jos — se activează imediat, fără să reinstalezi aplicația." },
  "plan.owner": { en: "Your store: all Pro features are included.", ro: "Magazinul tău: toate funcțiile Pro sunt incluse." },
  "plan.usedHeading": { en: "Orders checked this month", ro: "Comenzi verificate luna aceasta" },
  "plan.limitReached": { en: "Monthly limit reached — new orders won't be checked until next month.", ro: "Limita lunară a fost atinsă — comenzile noi nu mai sunt verificate până luna viitoare." },
  "plan.yourPlan": { en: "your plan", ro: "planul tău" },
  "plan.upgrade": { en: "Upgrade to {name}", ro: "Treci la {name}" },
  "plan.switch": { en: "Switch to {name}", ro: "Treci la {name}" },
  "plan.launch.title": { en: "Launch offer: −50% forever", ro: "Ofertă de lansare: −50% pentru totdeauna" },
  "plan.launch.body": { en: "Press the button and within 24 hours we unlock the half-price plans for you. You will see them here, on the plans page.", ro: "Apasă butonul și în maximum 24 de ore îți activăm planurile la jumătate de preț. Le vei vedea aici, pe pagina de planuri." },
