  "emails.soon": { en: "Email sending will be enabled soon. You can already prepare your settings and templates.", ro: "Trimiterea e-mailurilor se activează în curând. Poți pregăti deja setările și șabloanele." },
  "emails.enable": { en: "Automatically email customers who abandoned checkout", ro: "Trimite automat e-mailuri clienților care nu au finalizat comanda" },
  "emails.first": { en: "Send email 1 (about an hour after leaving the checkout)", ro: "Trimite e-mailul 1 (la aproximativ o oră după abandon)" },
  "emails.firstHelp": { en: "Turn off to send only the next-day reminder.", ro: "Debifează ca să trimiți doar reamintirea de a doua zi." },
  "emails.delay1": { en: "Send first email after (minutes)", ro: "Primul e-mail după (minute)" },
  "emails.delay1Help": { en: "Recommended: 60. The first hour brings the most recovered orders. Nothing is sent at night (22–8, customer's time) — the customer gets the morning email instead.", ro: "Recomandat: 60. Prima oră aduce cele mai multe comenzi recuperate. Noaptea (22–8, ora clientului) nu se trimite — clientul primește direct e-mailul de dimineață." },
  "emails.howTitle": { en: "How it works:", ro: "Cum funcționează:" },
  "emails.howBody": { en: " 1) after ~1 hour — an elegant reminder with the product from the cart, no discount; 2) the next day — “this color is selling out”: if the cart already had a discount (e.g. from a pop-up), we remind them of it; if not, we offer your discount; 3) on the third day — last chance with the bigger discount, valid only that day. It stops as soon as the customer orders.", ro: " 1) după ~1 oră — o reamintire elegantă cu produsul din coș, fără reducere; 2) a doua zi — „culoarea se epuizează”: dacă în coș avea deja o reducere (ex. din pop-up), îi amintim de ea; dacă nu, îi oferim reducerea ta; 3) a treia zi — ultima șansă, cu reducerea mai mare, valabilă doar în ziua respectivă. Se oprește imediat ce clientul comandă." },
  "emails.second": { en: "Send email 2 (next day)", ro: "Trimite e-mailul 2 (a doua zi)" },
  "emails.secondWhen": { en: "When email 2 is sent", ro: "Când se trimite e-mailul 2" },
  "emails.secondMorning": { en: "Next day, at the chosen time (customer's time)", ro: "A doua zi, la ora aleasă (ora clientului)" },
