  "emails.hour2": { en: "Email 2 time", ro: "Ora e-mailului 2" },
  "emails.hour2Help": { en: "Recommended: 10:00 — mornings get the most opens and orders.", ro: "Recomandat: 10:00 — dimineața e-mailurile au cele mai multe deschideri și comenzi." },
  "emails.hoursAfter": { en: "Hours after the first email", ro: "Ore după primul e-mail" },
  "emails.hoursAfterHelp": { en: "Recommended: 24.", ro: "Recomandat: 24." },
