  "emails.none": { en: "none", ro: "fără" },
  "emails.pct2Help": { en: "Usually the same as your pop-up. The code is personal and single-use.", ro: "De obicei aceeași ca în pop-up. Codul e personal, de unică folosință." },
  "emails.valid2": { en: "Email 2 code is valid for", ro: "Codul din e-mailul 2 e valabil" },
