  "emails.hour3": { en: "Email 3 time", ro: "Ora e-mailului 3" },
  "emails.hour3Help": { en: "Recommended: 12:00 — lunch break; the customer has the rest of the day for the “today only” offer.", ro: "Recomandat: 12:00 — pauza de prânz; clientul are tot restul zilei pentru oferta „doar azi”." },
  "emails.pct3": { en: "Email 3 discount", ro: "Reducerea din e-mailul 3" },
  "emails.pct3Help": { en: "Valid only that day, until 23:59 (customer's time).", ro: "Valabilă doar în ziua respectivă, până la 23:59 (ora clientului)." },
  "emails.combine": { en: "The email discount combines with the store's other discounts (e.g. on 2–3 products)", ro: "Reducerea din e-mail se cumulează cu alte reduceri ale magazinului (ex. la 2–3 produse)" },
  "emails.combineHelp": { en: "Unchecked (recommended): they don't add up — Shopify applies the bigger discount for the customer. Checked: they add up (the store's automatic discount must also allow combining).", ro: "Nebifat (recomandat): nu se cumulează — Shopify aplică reducerea cea mai mare pentru client. Bifat: se cumulează (reducerea automată a magazinului trebuie și ea să permită cumularea)." },
  "emails.onlyConsent": { en: "Only customers who opted in to emails", ro: "Doar clienților abonați la e-mailuri" },
  "emails.stockNote": { en: "We don't send reminders when the item in the cart is out of stock — you'll see these under Skipped.", ro: "Nu trimitem reamintiri când produsul din coș nu mai e pe stoc — le vezi la „Netrimise”." },
  "emails.onlyConsentHelp": { en: "Recommended for the EU (Germany: reminder emails without consent may be considered unsolicited advertising).", ro: "Recomandat pentru UE (Germania: e-mailurile de reamintire fără acord pot fi considerate publicitate nesolicitată)." },
